-- Obsidian Quill demo content: choice points and reading activity
-- Generated by scripts/demo/build-seed.mjs. Paste into the Supabase SQL editor and run.

begin;
-- Choice points
insert into public.choice_points (id, chapter_id, anchor_position, prompt) values ('cbddd4ff-0c56-5f43-a7a8-6c9759968691', 'df2eabe7-a24f-5c3e-a7d9-ba9a774654a6', 1, 'Taddeus offers Ilse his ink. Guild or Ashwright: who does she trust tonight?') on conflict do nothing;
insert into public.choice_options (id, choice_point_id, position, label, branch_body) values
  ('6246f92d-fff7-51d4-a4e6-eaf066a00faf', 'cbddd4ff-0c56-5f43-a7a8-6c9759968691', 1, 'Take Taddeus''s ink', 'The ink was warm in the bottle, the way the well was warm. Ilse uncorked it and the smell of smoke filled the room.

''You''ll draw better with this,'' Taddeus said. ''And you''ll owe me.'' She was already drawing.'),
  ('e9db5569-efd4-5150-a7b4-7f179ae847e0', 'cbddd4ff-0c56-5f43-a7a8-6c9759968691', 2, 'Go to Mother Agathe', 'The Guild Tower''s doors were open at midnight, which they never were. Mother Agathe was waiting at the top of the stairs with two cups of tea.

''Sit,'' she said. ''Let''s both be honest for once.'''),
  ('e525b176-ec6f-5328-a9f8-11b07e705cff', 'cbddd4ff-0c56-5f43-a7a8-6c9759968691', 3, 'Trust neither', 'Ilse locked the door, put the unfinished map on the table and drew a single line: the edge of the Unmarked, closed, owned by no one.

The city held its breath, and then accepted it.')
on conflict do nothing;
insert into public.choice_points (id, chapter_id, anchor_position, prompt) values ('75db832d-08bd-5598-ab9c-12abe36ec85d', 'acf8ec4c-0b6e-5ebc-a827-03bd8ae0641d', 2, 'Reyes gives Ama forty-eight hours. What does she do first?') on conflict do nothing;
insert into public.choice_options (id, choice_point_id, position, label, branch_body) values
  ('b3b34f66-40cc-5ee9-ab57-cddf95f7951f', '75db832d-08bd-5598-ab9c-12abe36ec85d', 1, 'Talk to the crystals', 'Ama sat in front of Bay Six''s sealed door with a headset and a notebook and simply started counting, one to ten, again and again.

At seven, the crystals began counting with her.'),
  ('a49b1f86-1662-5133-a0b5-79d85a671803', '75db832d-08bd-5598-ab9c-12abe36ec85d', 2, 'Back up the evidence', 'Ama copied every message into a dozen colony relay queues, hidden inside weather reports and supply orders.

Whatever happened on Kestrel, the record would survive it.')
on conflict do nothing;
insert into public.choice_points (id, chapter_id, anchor_position, prompt) values ('ccf4aa3b-d3fb-5346-aca7-75ad35e17706', 'ba709c7d-6058-5b3d-af78-2234b3259523', 1, 'The River Lord invites Aiko to follow her great-aunt. What does she fold?') on conflict do nothing;
insert into public.choice_options (id, choice_point_id, position, label, branch_body) values
  ('e4486937-3361-5a41-af6a-15263e70f69d', 'ccf4aa3b-d3fb-5346-aca7-75ad35e17706', 1, 'A crane to say goodbye', 'Aiko folded a crane from the last sheet of her grandmother''s paper and set it on the water. It turned once, as if bowing, and drifted toward the door in the river.

She did not follow it.'),
  ('eebfd729-70dc-5881-aebf-eafbbf31c593', 'ccf4aa3b-d3fb-5346-aca7-75ad35e17706', 2, 'A boat to visit', 'Aiko folded a small boat, just large enough for one, and promised herself she would come back before the cicadas sang.

The river carried her gently, and brought her home by dusk.'),
  ('ed440c50-89b2-5c72-ab35-c4f894b4fffd', 'ccf4aa3b-d3fb-5346-aca7-75ad35e17706', 3, 'Nothing at all', 'Aiko held the paper in her hands until it grew warm and did not fold it.

''Some doors,'' her grandmother said beside her, ''are better left as paper.''')
on conflict do nothing;

-- Fresh Shelf history: older books finished their first week long ago; new ones are mid-week.
update public.fresh_shelf_slots f set
  starts_at = s.published_at,
  ends_at = s.published_at + interval '7 days',
  impressions_served = case when s.published_at < now() - interval '7 days' then f.impressions_target
                            else (15 + floor(random() * 35))::int end
from public.stories s
where s.id = f.story_id and s.author_id in (select id from auth.users where email like '%@demo.obsidianquill.invalid');

-- Simulated readers (signed-out ids) for the past 30 days: each opens chapters in order, finishes with the
-- story's "stickiness", sometimes comes back on a later day. Deterministic thanks to setseed.
do $$
declare
  plan jsonb := '[{"sid":"38bf5630-62ec-54d4-af2b-f9b4c804b5f3","readers":40,"stick":0.76},{"sid":"05777f18-1094-593a-aa62-a5c8e1560e84","readers":79,"stick":0.42},{"sid":"a3c50a76-8cd6-561e-a2bc-56f43dace8ae","readers":30,"stick":0.37},{"sid":"e52b45b3-2a54-56cf-acb1-0637ace80fa8","readers":115,"stick":0.44},{"sid":"8543874c-59aa-5c49-a7a1-7ac4191db19f","readers":95,"stick":0.6},{"sid":"889c7e53-53ba-5022-a566-f39b3dc8b12c","readers":58,"stick":0.65},{"sid":"7cd412ed-2a47-53de-a984-e67d223c5649","readers":89,"stick":0.41},{"sid":"28fba78c-6ad1-5894-a2d1-78f8f994db83","readers":80,"stick":0.46},{"sid":"beb87e81-0de9-5bb9-afdf-d6a5634c0f32","readers":79,"stick":0.68},{"sid":"0d34a01c-205a-5dc5-aed1-7231e016c33a","readers":113,"stick":0.62},{"sid":"d7c9dac0-6e19-521b-ae48-f40d07b58268","readers":72,"stick":0.88},{"sid":"0bb4c1d7-958d-5c7f-a984-2ec5bb31b5ca","readers":47,"stick":0.61},{"sid":"93b29c91-ec51-57f0-a4b9-46560e64fb7e","readers":42,"stick":0.41},{"sid":"12ccfce4-55c7-5715-a619-c32aae79e154","readers":88,"stick":0.63},{"sid":"fe5a7c01-daca-566f-a1ab-0017b479c792","readers":66,"stick":0.63},{"sid":"e2e3cb86-6cd1-508d-acdf-397d3610522c","readers":54,"stick":0.45},{"sid":"49006ee7-0db1-5693-a80a-aad669125b6b","readers":77,"stick":0.41},{"sid":"4dd7bf9e-6351-5dfc-a998-683a27007786","readers":137,"stick":0.64},{"sid":"7a307cbd-2824-5884-aaf7-5b89bb6edbb7","readers":107,"stick":0.5},{"sid":"49af270f-d457-5324-a474-492be457e16f","readers":56,"stick":0.35},{"sid":"8d17853b-57c5-5d68-a337-45a575609c90","readers":45,"stick":0.68},{"sid":"af2bf517-2e7b-545b-a05f-12ccab8d958d","readers":82,"stick":0.36},{"sid":"e494bd08-63c6-55cd-aa8a-a20933c60adb","readers":28,"stick":0.42},{"sid":"cfefaaff-f064-5e08-a2c1-20ae2192cb6d","readers":88,"stick":0.89},{"sid":"6970c36d-a4d0-5de4-ab4d-beef4b5e228c","readers":19,"stick":0.55},{"sid":"e115cf2b-5a7e-5b67-a2a7-cfa3c6c07cc5","readers":110,"stick":0.57},{"sid":"e1cd2a03-2c69-5f07-a242-abe5f81563d1","readers":49,"stick":0.56},{"sid":"18d6bfd3-1cca-557d-aa3e-cb4fe15ec5eb","readers":76,"stick":0.57},{"sid":"054b855b-86c2-50d2-a240-01ecd72ce88f","readers":60,"stick":0.72},{"sid":"29d31a6b-dc05-58af-a39a-133d2a95b699","readers":71,"stick":0.63}]';
  b jsonb;
  reader int;
  anon text;
  depth int;
  n int;
  k int;
  t timestamptz;
  first_pub timestamptz;
  ch record;
begin
  -- Run once: if demo readers already exist, leave them as they are.
  if exists (select 1 from public.reading_events e join public.stories s on s.id = e.story_id
             where s.author_id in (select id from auth.users where email like '%@demo.obsidianquill.invalid') and e.anon_id is not null) then
    raise notice 'Demo reading activity already present; skipping.';
    return;
  end if;
  perform setseed(0.42);
  for b in select * from jsonb_array_elements(plan) loop
    select min(published_at), count(*) into first_pub, n from public.chapters where story_id = (b->>'sid')::uuid;
    for reader in 1 .. (b->>'readers')::int loop
      anon := gen_random_uuid()::text;
      t := greatest(first_pub, now() - interval '30 days') + random() * (now() - greatest(first_pub, now() - interval '30 days'));
      depth := 1;
      while depth < n and depth < 15 and random() < (b->>'stick')::numeric loop depth := depth + 1; end loop;
      k := 0;
      for ch in select id, number, published_at from public.chapters where story_id = (b->>'sid')::uuid order by number limit depth loop
        k := k + 1;
        t := greatest(t, ch.published_at) + random() * interval '40 minutes';
        exit when t > now();
        insert into public.reading_events (anon_id, story_id, chapter_id, event_type, created_at)
        values (anon, (b->>'sid')::uuid, ch.id, 'open', t);
        if k < depth or random() < (b->>'stick')::numeric then
          insert into public.reading_events (anon_id, story_id, chapter_id, event_type, created_at)
          values (anon, (b->>'sid')::uuid, ch.id, 'finish', t + interval '6 minutes');
        end if;
        if k = 3 and random() < (b->>'stick')::numeric * 0.6 then
          t := t + interval '1 day' + random() * interval '2 days';
          exit when t > now();
          insert into public.reading_events (anon_id, story_id, chapter_id, event_type, created_at)
          values (anon, (b->>'sid')::uuid, ch.id, 'return', t);
        end if;
      end loop;
    end loop;
  end loop;
end $$;

-- Compute scores and close finished Fresh Shelf weeks.
select public.refresh_discovery();
commit;
